DO $ddl$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.delete_warehouse_record(text,uuid[],numeric)'::regprocedure) INTO definition; definition:=replace(definition,'m.recipient_employee_id,m.recipient_name,''Отмена операции ''','m.recipient_employee_id,NULL,''Отмена операции '''); EXECUTE definition; END $ddl$; COMMENT ON FUNCTION public.delete_warehouse_record(text,uuid[],numeric) IS 'Warehouse/admin only locked deletion. Nonzero/linked products blocked; linked invoices blocked; immutable issue/reconciliation history cancelled via one stock reversal without supplier spending; audit and retry guard retained.';